function deleteProject(id){
  if(!id) return;
  // confirmation (keeps native confirm for simplicity inside Studio)
  if(!confirm('Delete project? This cannot be undone.')) return;
  // remove project
  if(state.projects && state.projects[id]){
    delete state.projects[id];
  }
  // pick a new active project if any left
  const remaining = Object.keys(state.projects || {});
  state.activeProjectId = remaining.length ? remaining[0] : null;
  saveState(state);
  console.debug('Project deleted:', id);
}

2) Replace renderProjectList() with this robust version

Find the old renderProjectList and replace it with:

function renderProjectList(){
  const list = document.getElementById('projectList');
  list.innerHTML='';
  const keys = Object.keys(state.projects).sort((a,b)=> state.projects[b].createdAt - state.projects[a].createdAt);
  if(keys.length===0){
    list.innerHTML = '<div class="small" style="padding:12px">No project yet. Click + New to create one.</div>';
    document.getElementById('projectTitle').innerText='No project';
    document.getElementById('projectDesc').innerText='Create a project to start the UX journey';
    return;
  }
  keys.forEach(k=>{
    const p = state.projects[k];
    const row = document.createElement('div');
    row.className='project-row';
    // Use data attributes on buttons so delegation picks them up reliably
    row.innerHTML = `
      <div style="flex:1">
        <div style="font-weight:700">${escapeHtml(p.title)}</div>
        <div class="small">${escapeHtml(p.desc)}</div>
      </div>
      <div style="display:flex;gap:6px">
        <button class="btn ghost" data-id="${k}" data-action="switch">Open</button>
        <button class="btn" data-id="${k}" data-action="delete">Delete</button>
      </div>
    `;
    list.appendChild(row);
  });
  // Update UI text
  updateActiveUI();
}


3) Add a single delegated click handler (attach once)

Find where you previously wired per-button listeners (near end of file or after renderProjectList()), and replace with this block. This ensures only a single listener handles Open/Delete clicks reliably:

// Delegated handler for project list buttons (attach once)
(function attachProjectListDelegation(){
  const list = document.getElementById('projectList');
  // detach previous if present
  if(window._uxmate_projectListHandler){
    list.removeEventListener('click', window._uxmate_projectListHandler);
  }
  const handler = function(e){
    const btn = e.target.closest('button[data-action]');
    if(!btn) return;
    const action = btn.dataset.action;
    const id = btn.dataset.id;
    if(!action || !id) return;
    if(action === 'switch'){
      state.activeProjectId = id;
      saveState(state);
      console.debug('Project switched:', id);
      return;
    }
    if(action === 'delete'){
      // call deleteProject which will saveState and re-render
      deleteProject(id);
      return;
    }
  };
  window._uxmate_projectListHandler = handler;
  list.addEventListener('click', handler);
})();

