1) UPDATED index.html — add this <script type="module"> near the top (inside <head> or before your main app script)

Replace previous partial/incomplete Firebase snippets with this full, safe initializer.

IMPORTANT: Replace the FIREBASE_CONFIG_PLACEHOLDER object with your real Firebase config from the console.

<!-- Firebase global init (put this in index.html before your main app script) -->
<script type="module">
/*
  GLOBAL FIREBASE INITIALIZER for UXMate
  - Replaces partial initialization errors ("No Firebase App '[DEFAULT]'")
  - Exposes window.FB with { app, auth, db, storage, doc, setDoc, getDoc, ref, uploadBytes, getDownloadURL, onAuthStateChanged }
  - Exposes window.uploadFileToFirebase(file) -> Promise<{ name, type, url, createdAt }>
  - Replace FIREBASE_CONFIG_PLACEHOLDER with your project's config from Firebase console.
*/

// ====== ====== Replace this object with your Firebase project's config ======
const FIREBASE_CONFIG_PLACEHOLDER = {
  apiKey: "REPLACE_API_KEY",
  authDomain: "REPLACE_PROJECT.firebaseapp.com",
  projectId: "REPLACE_PROJECT_ID",
  storageBucket: "REPLACE_PROJECT.appspot.com",
  messagingSenderId: "REPLACE_SENDER_ID",
  appId: "REPLACE_APP_ID"
};
// ==========================================================================

async function initFirebaseIfNeeded(config){
  // no config -> skip and leave offline-only behavior
  if(!config || !config.apiKey) {
    console.warn('Firebase config empty — running in offline/local mode.');
    return null;
  }

  // Avoid duplicate init
  if(window.FB && window.FB._initialized) {
    console.debug('Firebase already initialized (global).');
    return window.FB;
  }

  try{
    // dynamic imports (v10) via CDN
    const [{ initializeApp, getApps }, 
           { getAuth, signInAnonymously, onAuthStateChanged }, 
           { getFirestore, doc, setDoc, getDoc, onSnapshot },
           { getStorage, ref, uploadBytes, getDownloadURL }] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/10.6.0/firebase-app.js').then(m=>[m.initializeApp, m.getApps]),
      import('https://www.gstatic.com/firebasejs/10.6.0/firebase-auth.js'),
      import('https://www.gstatic.com/firebasejs/10.6.0/firebase-firestore.js'),
      import('https://www.gstatic.com/firebasejs/10.6.0/firebase-storage.js')
    ]).catch(e => { throw e; });

    // initialize app (safe if already exists)
    const app = (getApps && getApps().length) ? getApps()[0] : initializeApp(config);

    const auth = getAuth(app);
    const db = getFirestore(app);
    const storage = getStorage(app);

    // sign in anonymously (non-blocking)
    signInAnonymously(auth).catch(err => {
      // non-fatal, but log for debugging
      console.warn('Anonymous sign-in failed (non-fatal):', err);
    });

    // assemble small FB helper and expose globally
    window.FB = {
      _initialized: true,
      app, auth, db, storage,
      // firestore helpers
      doc, setDoc, getDoc, onSnapshot,
      // storage helpers
      ref, uploadBytes, getDownloadURL,
      onAuthStateChanged
    };

    // Expose a helper that uploads file and returns download URL
    window.uploadFileToFirebase = async function(file, options = {}) {
      if(!window.FB || !window.FB.storage) throw new Error('Firebase not initialized');
      const user = (window.FB.auth && window.FB.auth.currentUser) || { uid: 'anonymous' };
      const uid = user.uid || 'anonymous';
      const timestamp = Date.now();
      const safeName = (file.name || 'file').replace(/\s+/g,'_').slice(0,120);
      const path = `users/${uid}/assets/${timestamp}_${safeName}`;
      const storageRef = window.FB.ref(window.FB.storage, path);
      // upload bytes
      const result = await window.FB.uploadBytes(storageRef, file);
      const url = await window.FB.getDownloadURL(storageRef);
      return { name: file.name, type: file.type, url, createdAt: new Date().toISOString(), path };
    };

    // Optional: attempt to merge remote/local on auth ready
    window.FB.onAuthStateChanged(auth, async (user) => {
      try{
        if(!user) return;
        // very simple merge: if user doc exists, merge remote into localStorage, else write local to remote
        const userDocRef = window.FB.doc(window.FB.db, 'users', user.uid);
        const snap = await window.FB.getDoc(userDocRef);
        const localRaw = localStorage.getItem('uxmate_projects');
        let localObj = null;
        try { localObj = localRaw ? JSON.parse(localRaw) : null; } catch(e) { localObj = null; }
        if(snap.exists()){
          const remote = snap.data().projects || {};
          // merge with local (remote wins)
          const merged = { projects: {...(localObj?.projects || {}), ...remote}, activeProjectId: localObj?.activeProjectId || Object.keys(remote)[0] || null };
          localStorage.setItem('uxmate_projects', JSON.stringify(merged));
          console.debug('Merged remote projects into localStorage');
        } else if(localObj && Object.keys(localObj.projects || {}).length){
          // upload local to remote
          await window.FB.setDoc(userDocRef, { projects: localObj.projects }, { merge: true });
          console.debug('Uploaded local projects to Firestore');
        }
      }catch(e){ console.warn('FB auth merge issue', e); }
    });

    console.debug('Firebase initialized and ready.');
    return window.FB;
  }catch(err){
    console.error('initFirebaseIfNeeded error:', err);
    return null;
  }
}

// Immediately attempt to initialize (non-blocking). The app code can also call initFirebaseIfNeeded(config).
// This call will succeed only after you replace the placeholder above.
initFirebaseIfNeeded(FIREBASE_CONFIG_PLACEHOLDER);
</script>


Notes

Put this script before your main app script so window.FB and window.uploadFileToFirebase are available when app code runs.

If you prefer, you can remove the immediate call and call initFirebaseIfNeeded(...) from your app explicitly — but immediate init is simpler.

2) UPDATED App.tsx (React + TypeScript) — rely on global FB

This App.tsx snippet assumes your React app runs inside the same page and can access window.FB and window.uploadFileToFirebase. It safely waits for window.FB, uses it if present, and falls back to localStorage-only behavior.

Copy this as your App.tsx (or merge key parts if you have additional app code):

// App.tsx (TypeScript + React)
// This component demonstrates using the global Firebase initializer from index.html
import React, { useEffect, useState, useRef } from "react";

declare global {
  interface Window {
    FB?: any;
    uploadFileToFirebase?: (file: File) => Promise<any>;
  }
}

type Project = {
  id: string;
  title: string;
  desc?: string;
  notes?: string;
  assets?: Array<any>;
  stages?: Record<string, boolean>;
  createdAt?: string;
};

const STORAGE_KEY = 'uxmate_projects';

export default function App() {
  const [state, setState] = useState<{ projects: Record<string, Project>, activeProjectId: string | null }>({ projects: {}, activeProjectId: null });
  const [fbReady, setFbReady] = useState<boolean>(false);
  const mounted = useRef(false);

  // Load local state once
  useEffect(()=>{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(raw){
      try{ setState(JSON.parse(raw)); } catch(e) { console.warn('Could not parse local state', e); }
    }
    mounted.current = true;
    return ()=>{ mounted.current = false; };
  },[]);

  // Watch for global FB initialization
  useEffect(()=>{
    let interval: any = null;
    if(window.FB && window.FB._initialized) {
      setFbReady(true);
    } else {
      // poll for a short while — Studio environment may initialize scripts in unpredictable order
      interval = setInterval(()=> {
        if(window.FB && window.FB._initialized) {
          setFbReady(true);
          clearInterval(interval);
        }
      }, 500);
      // stop polling after 10s
      setTimeout(()=> { if(interval) clearInterval(interval); }, 10000);
    }
    return ()=> { if(interval) clearInterval(interval); };
  },[]);

  // Unified save: localStorage + optional Firestore (rely on global FB)
  async function saveState(newState: typeof state){
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
    setState(newState);
    // if FB available, push to Firestore under users/{uid}
    try{
      if(window.FB && window.FB.auth && window.FB.auth.currentUser) {
        const uid = window.FB.auth.currentUser.uid;
        const userDocRef = window.FB.doc(window.FB.db, 'users', uid);
        await window.FB.setDoc(userDocRef, { projects: newState.projects }, { merge: true });
        console.debug('Saved to Firestore for uid', uid);
      }
    }catch(e){ console.warn('Firestore save failed', e); }
  }

  // Create project helper
  function createProject(title: string, desc?: string){
    const id = 'p_' + Math.random().toString(36).slice(2,9);
    const p: Project = { id, title, desc, notes:'', assets:[], stages:{}, createdAt: new Date().toISOString() };
    const newProjects = {...state.projects, [id]: p};
    const newState = { projects: newProjects, activeProjectId: id };
    saveState(newState);
    console.debug('Project created:', id);
  }

  // Delete project helper
  function deleteProject(id: string){
    if(!id) return;
    if(!confirm('Delete project? This cannot be undone.')) return;
    const copy = {...state.projects};
    delete copy[id];
    const remaining = Object.keys(copy);
    const newActive = remaining.length ? remaining[0] : null;
    const newState = { projects: copy, activeProjectId: newActive };
    saveState(newState);
    console.debug('Project deleted:', id);
  }

  // Clear project data helper
  function clearProjectData(id: string){
    if(!id) return;
    if(!confirm('Clear notes, assets and stage progress for this project?')) return;
    const p = state.projects[id];
    if(!p) return;
    p.notes = '';
    p.assets = [];
    p.stages = {};
    const newState = { ...state, projects: {...state.projects, [id]: p} };
    saveState(newState);
    console.debug('Project cleared:', id);
  }

  // Upload file (large files): prefer global uploadFileToFirebase if available, else fallback to local dataURL.
  async function uploadFile(id: string, file: File){
    if(!id) throw new Error('No project id');
    try{
      if(window.uploadFileToFirebase) {
        // upload to Firebase Storage (global helper)
        const meta = await window.uploadFileToFirebase(file);
        // meta includes { name, type, url, createdAt, path }
        const p = state.projects[id];
        p.assets = [...(p.assets || []), meta];
        const newState = { ...state, projects: {...state.projects, [id]: p} };
        await saveState(newState);
        return meta;
      } else {
        // fallback: store as dataURL (small files only)
        const dataURL = await new Promise<string>((res, rej) => {
          const fr = new FileReader();
          fr.onload = ()=> res(fr.result as string);
          fr.onerror = rej;
          fr.readAsDataURL(file);
        });
        const meta = { name: file.name, type: file.type, dataURL, createdAt: new Date().toISOString() };
        const p = state.projects[id];
        p.assets = [...(p.assets || []), meta];
        const newState = { ...state, projects: {...state.projects, [id]: p} };
        await saveState(newState);
        return meta;
      }
    }catch(e){
      console.error('uploadFile error', e);
      throw e;
    }
  }

  // Example UI: simple list for demo (you will adapt to your existing layout)
  return (
    <div style={{padding:20}}>
      <h2>UXMate (React wrapper)</h2>
      <div>Firebase ready: {fbReady ? 'Yes' : 'No'}</div>

      <div style={{marginTop:12}}>
        <button onClick={()=>{ const t = prompt('Title?') || 'Untitled'; createProject(t); }}>Create Project</button>
      </div>

      <div style={{marginTop:12}}>
        <h3>Projects</h3>
        <ul>
          {Object.values(state.projects).map(p => (
            <li key={p.id}>
              <strong>{p.title}</strong> &nbsp;
              <button onClick={()=> { /* open logic depends on your app */ setState(s => ({...s, activeProjectId: p.id})); }}>Open</button>
              <button onClick={()=> deleteProject(p.id)}>Delete</button>
              <button onClick={()=> clearProjectData(p.id)}>Clear</button>
              <div style={{fontSize:12,color:'#666'}}>{p.desc}</div>
            </li>
          ))}
        </ul>
      </div>

      <div style={{marginTop:12}}>
        {state.activeProjectId ? (
          <div>
            <h4>Active: {state.projects[state.activeProjectId].title}</h4>
            <input type="file" onChange={async (e)=> {
              const f = e.target.files?.[0];
              if(!f) return;
              await uploadFile(state.activeProjectId!, f);
              alert('Uploaded');
            }} />
          </div>
        ) : <div>No active project</div>}
      </div>
    </div>
  );
}


Notes about App.tsx

It does not attempt to initialize Firebase. It checks window.FB / window.uploadFileToFirebase.

uploadFile chooses Firebase Storage upload if available; otherwise it falls back to dataURL (local).

Polling logic in useEffect handles the case where index.html loads Firebase slightly later than the React bundle (common in Studio).

